from pathlib import Path
import html
root=Path(__file__).resolve().parent.parent; out=root/'public/figures/diffatlas'; out.mkdir(parents=True,exist_ok=True)
def svg(name,title,desc,body,h=400):
 s=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 {h}" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(desc)}</desc><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#526880"/></marker></defs><rect width="900" height="{h}" rx="20" fill="#f0f5fa"/><style>text{{font-family:Arial,sans-serif;fill:#17304b;font-size:19px}}.small{{font-size:16px}}.title{{font-size:25px;font-weight:bold}}.line{{stroke:#526880;stroke-width:2.5;fill:none;marker-end:url(#arrow)}}</style><text x="30" y="42" class="title">{html.escape(title)}</text>{body}</svg>'''
 (out/f'{name}.svg').write_text(s)
def text(x,y,t,cls=''):return f'<text x="{x}" y="{y}" class="{cls}">{html.escape(t)}</text>'
def box(x,y,w,label,sub='',color='#dbece7'):
 return f'<rect x="{x}" y="{y}" width="{w}" height="86" rx="12" fill="{color}" stroke="#91a7b7"/>'+text(x+14,y+32,label)+text(x+14,y+60,sub,'small')
def arrow(x,y,x2,y2):return f'<path d="M{x},{y} L{x2},{y2}" class="line"/>'
svg('paradigms','01 / What object does the model learn?', 'Four segmentation paradigms contrasted: direct mapping, atlas registration, conditional mask diffusion, and joint image-mask diffusion.', ''.join(text(30,92+i*90,a)+box(280,58+i*90,260,b,c)+arrow(550,100+i*90,610,100+i*90)+box(625,58+i*90,245,d,e) for i,(a,b,c,d,e) in enumerate([
 ('Feedforward','Scan → network','learn a direct mapping','Mask','one forward pass'),('Classical atlas','Labeled reference pair','find a deformation φ','Warped atlas mask','S = Aₛ ∘ φ'),('Mask diffusion','Noisy mask + scan','learn p(S | I)','Denoised mask','scan is the condition'),('DiffAtlas','Noisy image + noisy SDF','learn p(I, S) jointly','Denoised pair','replace image at test time') ])),440)
svg('training','02 / Training: learn what belongs together','Clean scan and signed distance mask are noised together. A time-aware shared denoiser predicts noise for both. The squared error updates its weights.',box(30,100,230,'A · Clean pair x₀','[image I, mask SDF S]')+arrow(265,142,310,142)+box(320,100,240,'B · Add known noise','xₜ = √ᾱₜ x₀ + √(1−ᾱₜ) ε')+arrow(565,142,610,142)+box(620,100,250,'C · Shared denoiser','εθ(Iₜ, Sₜ, t)','#e4ddf6')+box(620,245,250,'D · Predict BOTH noises','[ε̂ image, ε̂ mask]','#e4ddf6')+arrow(745,190,745,235)+box(280,245,280,'E · Compare with true ε','L = E ‖ε − ε̂‖²','#ffe8cf')+arrow(615,287,570,287)+text(30,365,'Only training uses a ground-truth mask. The loss changes θ, the learned weights.'))
svg('sampling','03 / Inference: replace → denoise → repeat','At each time step, noise the observed scan to the matching noise level, replace only the image channels, and denoise the pair while retaining the evolving mask.',box(30,85,240,'Observed patient scan','Iinput stays available')+arrow(275,126,325,126)+box(340,85,250,'Noise to current t','√ᾱₜ Iinput + √(1−ᾱₜ) ε')+arrow(465,175,465,220)+box(340,235,250,'Replace IMAGE part','[new Iₜ, evolving Sₜ]','#ffe8cf')+box(30,235,240,'Current mask state Sₜ','start Sₜ with random noise')+arrow(275,277,330,277)+arrow(595,277,625,277)+box(635,235,235,'Same trained denoiser','then reverse-step sampler','#e4ddf6')+arrow(755,325,755,380)+box(620,390,250,'Next pair at t − 1','keep its mask; repeat')+f'<path d="M620,432 L150,432 L150,328" class="line"/>'+text(30,492,'Finish near t = 0 → decode the final SDF into segmentation labels.'),525)
body=''
for i,v in enumerate([3,2,1,0,-1,-2,-1,0,1,2,3]):
 x=45+i*74; c='#d3c1f0' if v<0 else '#ffe2bd' if v>0 else '#ffffff'
 body+=f'<rect x="{x}" y="135" width="70" height="75" rx="8" fill="{c}" stroke="#8599a9"/>'+text(x+25,180,str(v))
body+=text(35,98,'A one-dimensional slice through a toy organ: distance to the nearest boundary')+text(50,255,'Outside: positive')+text(335,255,'Inside: negative')+text(670,255,'Outside: positive')+text(45,315,'The zeros mark the boundary. Threshold at 0 to recover this binary toy mask.')+text(45,352,'Teaching convention: negative inside; the paper does not specify its sign convention.','small')
svg('sdf','04 / Give the mask a sense of distance', 'A signed distance field changes smoothly from positive outside through zero at the boundary to negative inside.',body)
svg('noise','05 / Why add noise to a perfectly good scan?', 'At high noise the denoiser expects a weak image signal; near the end it expects a clean image. The replacement must match that time.', ''.join(box(35+i*290,110,255,a,b)+text(50+i*290,235,c)+text(50+i*290,273,d,'small') for i,(a,b,c,d) in enumerate([('Early: ᾱ = 0.01','0.10 × scan + 0.995 × noise','Mostly noise','Weak patient-specific signal'),('Middle: ᾱ = 0.50','0.707 × scan + 0.707 × noise','Signal + uncertainty','Both coefficients are √0.5'),('Late: ᾱ = 0.99','0.995 × scan + 0.10 × noise','Mostly patient scan','Precise image information')]))+text(35,348,'ᾱ is remaining signal variance, not the fraction of clean pixels.'))
svg('numeric','06 / Follow one pair of numbers through training','Toy image and mask values with a known noise draw demonstrate forward corruption, noise prediction, loss, and clean reconstruction.',box(30,90,390,'Clean pair: x₀ = [0.8, −0.4]','Known noise: ε = [0.2, −1.0]')+box(470,90,395,'Choose ᾱ = 0.64','Signal weight 0.8; noise weight 0.6')+arrow(235,185,235,220)+box(30,230,390,'Noisy pair xₜ = [0.76, −0.92]','0.8 × x₀ + 0.6 × ε')+arrow(425,271,460,271)+box(470,230,395,'Suppose ε̂ = [0.1, −0.8]','Squared-error sum: 0.01 + 0.04 = 0.05')+text(35,373,'Clean estimate: (xₜ − 0.6 ε̂) / 0.8 = [0.875, −0.55]')+text(35,415,'With perfect noise prediction, this algebra recovers [0.8, −0.4] exactly.','small'),450)
body=text(30,88,'Average Dice (%) · five heart structures · higher is better','small')
for i,(label,a,b) in enumerate([('Full TS → TS',83.66,85.17),('2-shot CT → CT',46.96,77.73),('TS CT → MMWHS MRI',44.32,76.44)]):
 y=120+i*100;body+=text(30,y+20,label,'small')
 for j,(v,c) in enumerate([(a,'#758ba3'),(b,'#197f71')]):body+=f'<rect x="260" y="{y+j*32}" width="{v*5.3}" height="24" rx="4" fill="{c}"/>'+text(270+v*5.3,y+j*32+19,f'{v:.2f}','small')
body+=text(260,454,'Gray: nnU-Net     Green: DiffAtlas','small')+text(30,490,'Course PDF v1, Tables 1–3. Selected comparisons; full baseline table is below.','small')
svg('results','07 / Where is the evidence strongest?', 'Selected average Dice comparisons show small full-data gains on TS and larger gains in the two-shot and cross-modality settings.',body,520)
